parameters.value:
{
  "username": "ResponseLab",
  "embeds": [
    {
      "title": "$responselab.titulo_json",
      "color": $responselab.color,
      "description": "$responselab.resumen_json",
      "fields": [
        {
          "name": "Familia / clase",
          "value": "$responselab.familia / $responselab.clase",
          "inline": true
        },
        {
          "name": "Escalar a",
          "value": "$responselab.escalar_a en $responselab.plazo_min min",
          "inline": true
        },
        {
          "name": "Automatico",
          "value": "$responselab.automaticas_json"
        },
        {
          "name": "Espera aprobacion",
          "value": "$responselab.en_espera_json"
        },
        {
          "name": "Analisis IA",
          "value": "$limpiar.mensaje_json"
        }
      ]
    }
  ]
}
